"""Writes ../codecs_gen.go: run with the reference CPython 3.13.16
(python -I gen_codecs.py > ../codecs_gen.go; gofmt -w ../codecs_gen.go).

The table is what codecs.lookup(name).name answers for every name the
encodings package resolves: pyexpat's unknown-encoding handler builds the
single-byte map expat uses from `bytes.decode(name, 'replace')`.
"""
import codecs
import encodings
import encodings.aliases as aliases
import pkgutil

names = {}
modules = [module.name for module in pkgutil.iter_modules(encodings.__path__)]
for key in list(aliases.aliases) + modules:
    if key == 'aliases' or key.startswith('_'):
        continue
    try:
        info = codecs.lookup(key)
    except LookupError:
        continue
    if not getattr(info, '_is_text_encoding', True):
        continue
    names[key.lower()] = info.name

print('// Code generated by testdata/gen_codecs.py from the CPython 3.13.16 encodings package; DO NOT EDIT.')
print('package pandasxlsx')
print()
print('// codecNames maps a codec name normalized the way codecs.lookup does (encodings.normalize_encoding')
print('// of the lowered name, or an alias key) to codecs.lookup(name).name.')
print('var codecNames = map[string]string{')
for key in sorted(names):
    print('\t%s: %s,' % (repr(key).replace("'", '"'), repr(names[key]).replace("'", '"')))
print('}')
